def time_modes(t, q, n):
    from scipy.optimize import least_squares

    def basis(r):
        return -np.expm1(-t[:, None] * r)

    def err(r):
        h = basis(r)
        return (h @ np.linalg.lstsq(h, q[:n].T, rcond=None)[0] - q[:n].T).ravel()
    h = basis(np.sort(least_squares(err, [0.5, 2.0], bounds=(0.01, 10.0)).x))
    return (h, q @ np.linalg.pinv(h.T))

def _inverse(x, c):
    from scipy.optimize import least_squares

    def residual(z, row):
        w = np.roll(z, -1)
        return c[0] + c[1] * z + c[2] * w + c[3] * z * w + c[4] * z ** 3 - row
    return np.array([least_squares(residual, (row - c[0]) / c[1], args=(row,), gtol=1e-11).x for row in x])

def _modes(t, traj):
    from scipy.optimize import least_squares

    def basis(r):
        return -np.expm1(-t[:, None] * r)

    def project(h):
        return np.linalg.lstsq(h, traj.T, rcond=None)[0]

    def residual(r):
        h = basis(r)
        return (h @ project(h) - traj.T).ravel()
    r = least_squares(residual, [0.5, 2.0], bounds=(0.01, 10.0)).x
    h = basis(np.sort(r))
    return (h, project(h).T)

def _dictionary(z):
    from itertools import combinations
    from itertools import combinations_with_replacement
    x = z.T
    columns = [np.prod(x[list(ids)], axis=0) for k in range(1, 5) for ids in combinations_with_replacement(range(4), k)]
    for (i, j) in combinations(range(4), 2):
        w = x[i] * x[j]
        for k in (0.7, 1.5, 2.5, 3.5):
            columns.extend((np.sin(k * w), np.tanh(k * w), np.cos(k * w)))
    for (i, a) in enumerate(x):
        for k in (0.5, 1.0, 1.5, 2.0, 2.5, 3.0, 3.5, 4.0):
            for f in (np.sin(k * a), np.cos(k * a), np.tanh(k * a), 1 / (1 + k * a * a), a / (1 + k * a * a), np.sqrt(1 + k * a * a)):
                columns.append(f)
                columns.extend((b * f for (j, b) in enumerate(x) if i != j))
    return np.column_stack(columns)

def _ridge(features, y, reg):
    n = len(y)
    a = features[:n]
    f = (features - a.mean(axis=0)) / np.maximum(a.std(axis=0), 1e-12)
    a = f[:n]
    return y.mean(axis=0) + f[n:] @ a.T @ np.linalg.solve(a @ a.T + reg * np.eye(n), y - y.mean(axis=0))
